#!/usr/bin/env python3
"""Run unchanged source PreferencesScroll/ZoomManager with real Fumen numerical semantics.
Uses the sibling whole-group oracle's pinned external UI/cache host, not a replacement
Scroll model. KeyCommandManager is an explicit zoom/spacing flag adapter only.
"""
import argparse,hashlib,importlib.util,json,subprocess,tempfile
from pathlib import Path
PROGRAM='using System.Text.Json;using System.Reflection;using StepManiaEditor;\nclass Program{\n static void Main(){var output=new List<object>();foreach(var q in JsonDocument.Parse(Console.In.ReadToEnd()).RootElement.EnumerateArray()){\n  var path=Path.GetTempFileName();File.WriteAllText(path,q.GetProperty("raw").GetString());var p=Preferences.Load(new Editor(),path).PreferencesScroll;File.Delete(path);var stages=new List<object>();\n  try{var manager=new ZoomManager();\n   double axis(string name){var value=typeof(ZoomManager).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(manager);return(double)value.GetType().GetMethod("GetValue").Invoke(value,null);}\n   object capture()=>new{zoom=manager.GetSpacingZoom(),size=manager.GetSizeZoom(),cap=manager.GetSizeCap(),time=axis("ConstantTimeSpacingData"),row=axis("ConstantRowSpacingData"),variable=axis("VariableSpacingData"),rawCap=p.SizeCap,duration=p.ScrollInterpolationDuration,multiplier=p.ZoomMultiplier,limited=p.LimitZoomToSize};\n   stages.Add(capture());foreach(var op in q.GetProperty("ops").EnumerateArray()){\n    switch(op[0].GetString()){\n     case"duration":p.ScrollInterpolationDuration=op[1].GetDouble();break;case"multiplier":p.ZoomMultiplier=op[1].GetDouble();break;case"cap":p.SizeCap=op[1].GetDouble();break;case"limit":p.LimitZoomToSize=op[1].GetBoolean();break;case"zoom":manager.SetZoom(op[1].GetDouble());break;\n     case"scroll":manager.ProcessInput(op[1].GetDouble(),new KeyCommandManager(op[3].GetBoolean(),op[4].GetBoolean()),op[2].GetSingle());break;case"update":manager.Update(op[1].GetDouble());break;\n    }stages.Add(capture());\n   }output.Add(new{name=q.GetProperty("name").GetString(),raw=q.GetProperty("raw").GetString(),ops=q.GetProperty("ops").Clone(),stages,error=(string)null});\n  }catch(Exception e){output.Add(new{name=q.GetProperty("name").GetString(),raw=q.GetProperty("raw").GetString(),ops=q.GetProperty("ops").Clone(),stages,error=e.GetType().Name});}\n }Console.Write(JsonSerializer.Serialize(output));}\n}\n'
REQUESTS=[{'name': 'constructor-raw4-duration-only-cap-notification', 'raw': '{"PreferencesScroll": {"SizeCap": 4, "LimitZoomToSize": true, "ScrollInterpolationDuration": 2.5, "ZoomMultiplier": 0.3}}', 'ops': [['zoom', 3], ['duration', 3.5], ['scroll', 0, 0.5, True, False], ['update', 1.75], ['cap', 2], ['zoom', 3], ['duration', -2], ['scroll', 10, -0.5, True, False], ['update', 9]]}, {'name': 'negative-raw-unlimited', 'raw': '{"PreferencesScroll": {"SizeCap": -2, "LimitZoomToSize": false, "ScrollInterpolationDuration": -2, "ZoomMultiplier": -1}}', 'ops': [['scroll', 10, 0.3, True, False], ['update', 9], ['update', 11], ['cap', -3], ['limit', True], ['duration', 3], ['scroll', 12, -3, True, False], ['update', 15]]}, {'name': 'zero-multiplier-positive-negative-deltas', 'raw': '{"PreferencesScroll": {"ZoomMultiplier": 0, "ScrollInterpolationDuration": 0}}', 'ops': [['scroll', 0, 1, True, False], ['update', 0], ['zoom', 1], ['scroll', 1, -1, True, False], ['update', 1]]}, {'name': 'decreasing-positive-multiplier-saturated', 'raw': '{"PreferencesScroll": {"ZoomMultiplier": 0.3, "ScrollInterpolationDuration": 2}}', 'ops': [['scroll', 0, 3, True, False], ['update', 1], ['update', 2], ['scroll', 2, -3, False, True], ['update', 4]]}, {'name': 'negative-cap-inverted-bounds', 'raw': '{"PreferencesScroll": {"SizeCap": -2, "LimitZoomToSize": true}}', 'ops': []}, {'name': 'constructor-one-ulp-cap-source-setter', 'raw': '{"PreferencesScroll": {"SizeCap": 1.0000000000000002, "LimitZoomToSize": true}}', 'ops': [['zoom', 2]]}, {'name': 'zero-cap-unlimited', 'raw': '{"PreferencesScroll": {"SizeCap": 0}}', 'ops': [['scroll', 0, 0.25, True, False], ['update', 0.1]]}]
KEY_HOST='namespace StepManiaEditor{class KeyCommandManager(bool zoom,bool spacing){public bool IsAnyInputDown(System.Collections.Generic.List<Microsoft.Xna.Framework.Input.Keys[]> query)=>Object.ReferenceEquals(query,Preferences.Instance.PreferencesKeyBinds.ScrollZoom)?zoom:spacing;}}'
def main():
 p=argparse.ArgumentParser(description=__doc__)
 for name in ['source','reference-root','dotnet','output']:p.add_argument('--'+name,type=Path,required=True)
 a=p.parse_args();spec=importlib.util.spec_from_file_location('groups',Path(__file__).with_name('editor-global-preferences-groups-reference.py'));g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
 for root,pin in [(a.source,g.EDITOR_PIN),(a.reference_root,g.LIBRARY_PIN),(a.reference_root/'Fumen',g.FUMEN_PIN)]:assert g.git(root,'rev-parse','HEAD').decode().strip()==pin
 dll=a.reference_root/'Fumen/Fumen/bin/Release/net10.0/Fumen.dll';assert dll.exists()
 keys=Path(__file__).with_name('editor-source-import-oracle')/'Keys.cs';assert hashlib.sha256(keys.read_bytes()).hexdigest()==g.KEYS_SHA
 hashes={}
 with tempfile.TemporaryDirectory(prefix='source-loaded-zoom-')as folder:
  work=Path(folder)
  for name in ['Preferences']+['Preferences'+n for n in g.GROUPS]:
   path='StepManiaEditor/Preferences/'+name+'.cs';raw=g.original(a.source,path);hashes[path]=hashlib.sha256(raw).hexdigest();(work/(name+'.cs')).write_bytes(raw)
  for path in ['StepManiaEditor/SubdivisionType.cs','StepManiaEditor/ZoomManager.cs']:
   raw=g.original(a.source,path);hashes[path]=hashlib.sha256(raw).hexdigest();(work/Path(path).name).write_bytes(raw)
  raw=g.original(a.source,'StepManiaEditor/MiniMap.cs');hashes['StepManiaEditor/MiniMap.cs']=hashlib.sha256(raw).hexdigest();mini=raw.decode('utf-8-sig')
  host=g.HOST.replace('ENUMS',g.member(mini,'Position')+g.member(mini,'SelectMode'))+KEY_HOST
  (work/'Host.cs').write_text(host);(work/'Program.cs').write_text(PROGRAM);(work/'Keys.cs').write_bytes(keys.read_bytes())
  (work/'Oracle.csproj').write_text(f'<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings></PropertyGroup><ItemGroup><Reference Include="Fumen"><HintPath>{dll}</HintPath></Reference></ItemGroup></Project>')
  r=subprocess.run([str(a.dotnet),'build',str(work/'Oracle.csproj'),'-c','Release','--nologo','-v','q','-p:WarningLevel=0'],capture_output=True,text=True)
  if r.returncode:raise SystemExit(r.stdout+r.stderr)
  binary=work/'bin/Release/net10.0/Oracle.dll';r=subprocess.run([str(a.dotnet),str(binary)],input=json.dumps(REQUESTS),capture_output=True,text=True,check=True);data=json.loads(r.stdout)
  provenance=dict(editor_commit=g.EDITOR_PIN,library_commit=g.LIBRARY_PIN,fumen_commit=g.FUMEN_PIN,source_sha256=hashes,host_sha256=hashlib.sha256(host.encode()).hexdigest(),program_sha256=hashlib.sha256(PROGRAM.encode()).hexdigest(),assembly_sha256=hashlib.sha256(binary.read_bytes()).hexdigest(),fumen_assembly_sha256=hashlib.sha256(dll.read_bytes()).hexdigest(),scope=__doc__)
 a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(json.dumps(data,indent=2)+'\n');a.output.with_suffix('.reference.json').write_text(json.dumps(provenance,indent=2)+'\n');print('Executed',len(data),'source loaded zoom traces,',sum(len(c['stages'])for c in data),'states')
if __name__=='__main__':main()
